INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('semis', 'CHIPS', 'On average, how many dollars of semiconductors were sold worldwide every second in 2025?', 'US dollars per second', 25228, 'revenue', 'Chip sales are somewhere around $800 billion a year, and a year has about 31.5 million seconds.', 'WSTS reports $795.6 billion for 2025. Divided by the 31,536,000 seconds in a year, that is about $25,200 a second. The Semiconductor Industry Association''s earlier figure was $791.7 billion.', 'WSTS, Global Semiconductor Market grows 26% in 2025', 'https://www.wsts.org/76/103/Global-Semiconductor-Market-grows-26-in-2025-to-796B', '2025 full year, final WSTS data (March 2026)', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('visatx', 'MARKETS', 'On average, how many transactions did Visa process every second in its 2025 fiscal year?', 'transactions per second', 8165, 'visa', 'Hundreds of billions of transactions a year, divided by about 31.5 million seconds.', 'Visa reports 257.5 billion transactions for fiscal 2025. That is about 8,165 a second on average. The network can handle far more at peak, so the average is well below capacity.', 'Visa fiscal 2025 annual report', 'https://s29.q4cdn.com/385744025/files/doc_downloads/2025/Visa-Fiscal-2025-Annual-Report.pdf', 'Fiscal 2025 (to September 2025)', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('visaavg', 'MARKETS', 'On average, how many dollars was each transaction on Visa''s network worth in fiscal 2025?', 'US dollars per transaction', 64.85, 'visa', 'Most card payments are everyday purchases of a few dollars to a few hundred, so an average somewhere around $50 to $100.', 'Visa reports $16.7 trillion of total volume over 257.5 billion transactions, which is about $64.85 each. Both figures include cash withdrawals as well as purchases.', 'Visa fiscal 2025 annual report', 'https://s29.q4cdn.com/385744025/files/doc_downloads/2025/Visa-Fiscal-2025-Annual-Report.pdf', 'Fiscal 2025 (to September 2025)', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('tesla', 'MARKETS', 'How many vehicles did Tesla deliver in 2025?', 'vehicles', 1636129, NULL, 'Tesla delivered about 1.8 million in 2024 and sales fell in 2025, so somewhere around 1.6 million.', 'Down 8.6% from 1,789,226 in 2024, after the US federal EV tax credit ended on September 30, 2025. This figure comes from secondary coverage of Tesla''s own release.', 'Not a Tesla App, Tesla Q4 2025 report', 'https://www.notateslaapp.com/news/3468/tesla-reports-q4-delivery-numbers-narrowly-misses-on-deliveries-energy-hits-record', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('phones', 'TECH', 'On average, how many smartphones were shipped worldwide every minute in 2025?', 'smartphones per minute', 2397, NULL, 'About 1.25 billion phones a year, and a year has about 525,600 minutes.', 'IDC reports about 1.26 billion shipments for 2025. Divided by the 525,600 minutes in a year, that is about 2,400 a minute. Omdia counted 1.25 billion.', 'IDC smartphone tracker, January 2026', 'https://www.idc.com/?p=107472', '2025 full year, preliminary', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('domains', 'TECH', 'What percentage of all registered domain names end in .com or .net?', 'percent', 44.6, NULL, '.com is by far the biggest extension, with hundreds of rivals splitting the rest.', 'Verisign''s Q2 2026 report counts 179.1 million .com and .net names out of 401.6 million in total, which is 44.6%. The figures are from June 30, 2026.', 'Verisign Q2 2026 Domain Name Industry Brief', 'https://blog.verisign.com/domain-names/q2-2026-domain-name-industry-brief-quarterly-report/', 'June 30, 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('starlink', 'TECH', 'How many Starlink satellites are active in orbit?', 'satellites', 10838, NULL, 'SpaceX launches about 25 satellites per Falcon 9 and flies one every few days, so a few thousand a year, on top of the 10,000 reached in March 2026.', 'KeepTrack, a third-party tracker, counted 11,131 in orbit and 10,838 active in October 2026. Its catalog lags recent launches, so the true number is higher. This is not an official SpaceX figure.', 'KeepTrack, Starlink satellite count', 'https://keeptrack.space/starlink-satellite-count', 'October 2026, KeepTrack', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('hashrate', 'CRYPTO', 'What was the Bitcoin network''s average hashrate over the 30 days to the end of August 2026?', 'exahashes per second', 912, NULL, 'It passed 1,000 EH/s in January 2026 and has been in the high hundreds since.', 'Hashrate Index gives a 30-day average of 912 EH/s and a 7-day average of 915 EH/s at August 31, 2026. Hashrate is estimated, not measured directly, so sources differ. One estimate for August 26 was about 860.', 'Hashrate Index roundup, August 31, 2026', 'https://hashrateindex.com/blog/hashrate-index-roundup-august-17-2026-2/', '30 days to August 31, 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('btcnew', 'CRYPTO', 'How many new bitcoin are created every day?', 'bitcoin per day', 450, NULL, 'A block arrives about every 10 minutes, so 144 a day. Each block creates a fixed reward that halves every four years, and it is a few bitcoin now.', 'The reward is 3.125 bitcoin per block since the April 2024 halving, and there are about 144 blocks a day, so about 450. The next halving is expected in 2028.', 'Mudrex Learn, citing August 2026 data', 'https://mudrex.com/learn/?p=88362', '2026, until the next halving', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('nvrev', 'CHIPS', 'On average, how many dollars of revenue did Nvidia earn every second in its 2026 fiscal year?', 'US dollars per second', 6846, 'revenue', 'Nvidia made around $200 billion that year, divided by about 31.5 million seconds.', 'Nvidia reported $215.9 billion for fiscal 2026, which ended January 25, 2026. That works out to about $6,850 a second.', 'Nvidia Q4 and fiscal 2026 results (SEC 8-K)', 'https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm', 'Fiscal 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('nvdc', 'CHIPS', 'What percentage of Nvidia''s fiscal 2026 revenue came from its Data Center segment?', 'percent', 89.7, 'revenue', 'Gaming and other businesses are small next to AI chips now, so most of the revenue is data center.', 'Data Center was $193.7 billion of $215.9 billion total, which is 89.7%.', 'Nvidia Q4 and fiscal 2026 results (SEC 8-K)', 'https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm', 'Fiscal 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('tsmcrev', 'CHIPS', 'On average, how many dollars of revenue did TSMC earn every second in 2025?', 'US dollars per second', 3882, 'revenue', 'TSMC made roughly $120 billion in 2025, divided by about 31.5 million seconds.', 'TSMC''s 2025 revenue was about $122.4 billion (NT$3.81 trillion), which is about $3,880 a second. The dollar figure comes from secondary coverage of TSMC''s results, so check TSMC''s own release.', 'TelecomLead, TSMC 2025 results', 'https://telecomlead.com/semiconductor/tsmc-delivers-record-2025-revenue-and-profit-as-ai-chip-demand-fuels-growth-us-expansion-accelerates-124150', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('hynix', 'CHIPS', 'What percentage of the world''s DRAM sales did SK hynix make in the third quarter of 2025?', 'percent', 33.2, NULL, 'Three makers (SK hynix, Samsung and Micron) split most of the market, so the leader has around a third.', 'TrendForce reports SK hynix had $13.75 billion of $41.4 billion, a 33.2% share, just ahead of Samsung at 32.6%.', 'Evertiq, citing TrendForce', 'https://evertiq.com/design/2025-11-26-global-dram-revenue-jumps-309-in-3q25', 'Q3 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('asml', 'CHIPS', 'How many new lithography machines did ASML sell in 2025?', 'machines', 300, NULL, 'These machines cost tens of millions to hundreds of millions each, and ASML makes about $30 billion a year, so a few hundred.', 'Heise reports ASML sold 300 new and 27 refurbished systems in 2025, 91 fewer than in 2024. These are all lithography systems, not only the EUV models. The count is from secondary coverage, so check ASML''s annual report.', 'Heise, ASML record orders', 'https://heise.de/-11157655', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('chatgpt', 'TECH', 'What percentage of ChatGPT''s weekly users pay for a subscription?', 'percent', 5.6, 'users', 'Most people use free AI chat. A small slice pay, probably under one in ten.', 'OpenAI announced 900 million weekly users and 50 million paying subscribers on February 27, 2026, which is 5.6%. Weekly users and subscribers are different measures, so this is a rough ratio.', 'TechCrunch, ChatGPT reaches 900M weekly active users', 'https://techcrunch.com/2026/02/27/chatgpt-reaches-900m-weekly-active-users', 'February 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('spotify', 'TECH', 'What percentage of Spotify''s monthly active users pay for Premium?', 'percent', 38.6, 'users', 'Spotify has a large free tier, so perhaps a third to a half pay.', 'Spotify reported 300 million Premium subscribers and 777 million monthly active users in Q2 2026, which is 38.6%.', 'Spotify Q2 2026 results (SEC 6-K)', 'https://www.sec.gov/Archives/edgar/data/0001639920/000114036126031044/ef20078867_ex99-1.htm', 'Q2 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('wikien', 'TECH', 'How many articles does the English Wikipedia have?', 'articles', 7250000, NULL, 'It passed 7 million in May 2025 and grows by roughly 150,000 to 200,000 a year.', 'The count on the English Wikipedia page was 7,250,570 when checked. It changes daily, so update it from Wikipedia:Statistics shortly before publishing.', 'English Wikipedia', 'https://en.wikipedia.org/wiki/English_Wikipedia', 'October 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('hfmodels', 'CODE', 'How many public models are hosted on the Hugging Face Hub?', 'models', 3012377, NULL, 'It had about 2.4 million in January 2026 and has been adding over a million a year.', 'One third-party tally counts 3,012,377 on August 22, 2026, and Hugging Face''s own summer 2026 report says about 2.96 million. The count is live and grows daily.', 'Voxbooster Hugging Face statistics 2026 (third-party tally)', 'https://voxbooster.com/blog/hugging-face-model-downloads-statistics-2026/', 'August 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('ipos', 'MARKETS', 'How many companies went public on US stock exchanges in 2025?', 'IPOs', 202, NULL, 'A normal year has 150 to 250 sizeable IPOs and 2025 was a recovery year.', 'Renaissance Capital counts 202 IPOs raising $44.0 billion. It excludes SPACs, closed-end funds and companies below a $50 million market cap, and other counts including SPACs reach 354.', 'Renaissance Capital, 2025 US IPO Review', 'https://www.renaissancecapital.com/review/2025USReview_Public.pdf', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('etfs', 'MARKETS', 'How many exchange-traded funds were there in the United States at the end of 2025?', 'ETFs', 4813, NULL, 'The US passed 4,000 ETFs in 2024 and new launches keep coming, so about 4,500 to 5,000.', 'The ICI 2026 Fact Book says 4,813 including ETFs that invest in other ETFs. An ICI FAQ page gives 4,495 for US-domiciled ETFs, so the definition matters.', 'ICI 2026 Fact Book, chapter 2', 'https://icifactbook.org/pdf/2026-factbook-ch2.pdf', 'End of 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('vc', 'MARKETS', 'On average, how many dollars of venture and growth funding did startups raise worldwide every second in 2025?', 'US dollars per second', 13477, 'revenue', 'A few hundred billion dollars a year, divided by about 31.5 million seconds.', 'Crunchbase says about $425 billion in 2025, which is about $13,500 a second. CB Insights says $469 billion and PitchBook and KPMG say over $512 billion, so every tracker differs. The Crunchbase figure is relayed by secondary sources.', 'Crunchbase News, 2025 year-end funding', 'https://news.crunchbase.com/fintech/funding-jumped-big-checks-ai-ye-2025/', '2025 full year, Crunchbase', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('applerev', 'MARKETS', 'On average, how many dollars of sales did Apple make every second in its 2025 fiscal year?', 'US dollars per second', 13196, 'revenue', 'Apple makes around $400 billion a year, divided by about 31.5 million seconds.', 'Apple reported $416.2 billion for fiscal 2025, which is about $13,200 a second. Its fiscal year is 52 weeks, so the exact figure is a fraction of a percent higher.', 'Apple Form 10-K, fiscal 2025', 'https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/aapl-20250927.htm', 'Fiscal 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('aws', 'TECH', 'On average, how many dollars of revenue did Amazon Web Services earn every second in 2025?', 'US dollars per second', 4081, 'revenue', 'AWS makes more than $100 billion a year, divided by about 31.5 million seconds.', 'AWS reported $128.7 billion for 2025, which is about $4,080 a second.', 'Amazon Q4 2025 results', 'https://www.businesswire.com/news/home/20260204777163/en/Amazon.com-Announces-Fourth-Quarter-Results', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('amazon', 'MARKETS', 'On average, how many dollars of sales did Amazon make every second in 2025?', 'US dollars per second', 22733, 'revenue', 'Amazon sells hundreds of billions a year, divided by about 31.5 million seconds.', 'Amazon reported $716.9 billion in net sales for 2025, which is about $22,700 a second.', 'Amazon Q4 2025 results', 'https://www.businesswire.com/news/home/20260204777163/en/Amazon.com-Announces-Fourth-Quarter-Results', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('dcpower', 'TECH', 'How much electricity did data centers around the world use in 2025?', 'terawatt-hours', 485, NULL, 'The whole world uses about 30,000 TWh a year, and data centers are in the region of 1.5 to 2% of that.', 'The IEA estimated 416 TWh in 2024 and about 485 TWh in 2025, with 155 TWh for AI-focused sites. An earlier IEA rounding says about 500. These are estimates, relayed by Our World in Data.', 'Our World in Data, citing the IEA', 'https://ourworldindata.org/how-much-energy-do-data-centers-and-artificial-intelligence-use', '2025 estimate', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('internet', 'TECH', 'What percentage of the world''s people used the internet in 2025?', 'percent', 74, NULL, 'Most of the world is online by now, with large offline pockets in poorer regions.', 'The ITU says about three-quarters of the world, roughly 6 billion people, were online in 2025. The 74% figure comes from secondary coverage of the full report, so check it against the ITU report.', 'ITU, Facts and Figures 2025', 'https://www.itu.int/en/mediacentre/Pages/PR-2025-11-17-Facts-and-Figures.aspx', '2025 estimate', 'draft');
